import 'dart:async';import 'dart:math';import 'package:flutter/material.dart';
class RhythmTapGame extends StatefulWidget{const RhythmTapGame({super.key});@override State<RhythmTapGame> createState()=>_RhythmTapGameState();}
class _RhythmTapGameState extends State<RhythmTapGame>{Timer? t;final r=Random();int beat=0,score=0;DateTime next=DateTime.now();@override void initState(){super.initState();t=Timer.periodic(const Duration(milliseconds:500),(_){if(mounted)setState(()=>beat=(beat+1)%4);});}void tap(){final d=DateTime.now().difference(next).inMilliseconds.abs();setState(()=>score+=d<180?3:d<320?1:0);next=DateTime.now().add(Duration(milliseconds:250+r.nextInt(250)));}@override void dispose(){t?.cancel();super.dispose();}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Rhythm Tap')),body:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text('النقاط: $score',style:const TextStyle(fontSize:24,fontWeight:FontWeight.w900)),const SizedBox(height:30),AnimatedScale(scale:beat.isEven?1.0:1.12,duration:const Duration(milliseconds:180),child:FilledButton(onPressed:tap,style:FilledButton.styleFrom(shape:const CircleBorder(),padding:const EdgeInsets.all(60)),child:const Text('TAP')))])));}